  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "For each product and quarter, is the contract reservation a minimum amount that must be delivered (with any extra production allowed to be carried as inventory), or an exact amount that must be delivered (so producing more than the reservation in that quarter is not permitted)?"
  ],
  "rationale": "The response asks for a single policy choice regarding the nature of the contract reservation (minimum vs. exact), which constitutes one semantically independent question."
}

